function grade(score) {
  if (score >= 70) return "A";
  if (score >= 50) return "C";
  return "Fail";
}
const students = [
  { name: "Amina", score: 78 },
  { name: "Tunde", score: 54 },
  { name: "Grace", score: 41 }
];
let total = 0;
let best = students[0];
for (const s of students) {
  console.log(`${s.name} ${s.score} ${grade(s.score)}`);
  total += s.score;
  if (s.score > best.score) best = s;
}
console.log(`Average: ${(total / students.length).toFixed(1)}`);
console.log(`Best: ${best.name}`);

